def try_merge(a: str, b: str) -> list[str]:
    """Try raw concatenation and overlap-removed concatenation."""
    merges = [a + b, b + a]
    for k in range(1, min(len(a), len(b)) + 1):
        if a[-k:] == b[:k]:
            merges.append(a + b[k:])
        if b[-k:] == a[:k]:
            merges.append(b + a[k:])
    return list(set(merges))

